   125  static int
   126  json_parse_string(const unsigned char **ucp, const unsigned char *ue,
   127      size_t lvl __file_debugused)
   128  {
   129          const unsigned char *uc = *ucp;
   130          size_t i;
   131
   132          DPRINTF("Parse string: ", uc, *ucp);
   133          while (uc < ue) {
   134                  switch (*uc++) {
   135                  case '\0':
   136                          goto out;
   137                  case '\\':
   138                          if (uc == ue)
   139                                  goto out;
   140                          switch (*uc++) {
   141                          case '\0':
   142                                  goto out;
   143                          case '"':
   144                          case '\\':
   145                          case '/':
   146                          case 'b':
   147                          case 'f':
   148                          case 'n':
   149                          case 'r':
   150                          case 't':
   151                                  continue;
   152                          case 'u':
   153                                  if (ue - uc < 4) {
   154                                          uc = ue;
   155                                          goto out;
   156                                  }
   157                                  for (i = 0; i < 4; i++)
   158                                          if (!json_isxdigit(*uc++))
   159                                                  goto out;
   160                                  continue;
   161                          default:
   162                                  goto out;
   163                          }
   164                  case '"':
   165                          DPRINTF("Good string: ", uc, *ucp);
   166                          *ucp = uc;
   167                          return 1;
   168                  default:
   169                          continue;
   170                  }
   171          }
   172  out:
   173          DPRINTF("Bad string: ", uc, *ucp);
   174          *ucp = uc;
   175          return 0;
   176  }
