   320  static int
   321  json_parse_const(const unsigned char **ucp, const unsigned char *ue,
   322      const char *str, size_t len, size_t lvl __file_debugused)
   323  {
   324          const unsigned char *uc = *ucp;
   325
   326          DPRINTF("Parse const: ", uc, *ucp);
   327          for (len--; uc < ue && --len;) {
   328                  if (*uc++ == *++str)
   329                          continue;
   330          }
   331          if (len)
   332                  DPRINTF("Bad const: ", uc, *ucp);
   333          *ucp = uc;
   334          return len == 0;
   335  }
   336
   337  static int
   338  json_parse(const unsigned char **ucp, const unsigned char *ue,
   339      size_t *st, size_t lvl)
   340  {
   341          const unsigned char *uc;
   342          int rv = 0;
   343          int t;
   344
   345          uc = json_skip_space(*ucp, ue);
   346          if (uc == ue)
   347                  goto out;
   348
   349          // Avoid recursion
   350          if (lvl > 500) {
   351                  DPRINTF("Too many levels", uc, *ucp);
   352                  return 0;
   353          }
   354  #if JSON_COUNT
   355          /* bail quickly if not counting */
   356          if (lvl > 1 && (st[JSON_OBJECT] || st[JSON_ARRAYN]))
   357                  return 1;
   358  #endif
   359
   360          DPRINTF("Parse general: ", uc, *ucp);
file: could not find any valid magic files! (No such file or directory)

360          DPRINTF("Parse general: ", uc, *ucp);
   361          switch (*uc++) {
   362          case '"':
   363                  rv = json_parse_string(&uc, ue, lvl + 1);
   364                  t = JSON_STRING;
   365                  break;
   366          case '[':
   367                  rv = json_parse_array(&uc, ue, st, lvl + 1);
   368                  t = JSON_ARRAY;
   369                  break;
   370          case '{': /* '}' */
   371                  rv = json_parse_object(&uc, ue, st, lvl + 1);
   372                  t = JSON_OBJECT;
   373                  break;
   374          case 't':
   375                  rv = json_parse_const(&uc, ue, "true", sizeof("true"), lvl + 1);
   376                  t = JSON_CONSTANT;
   377                  break;
   378          case 'f':
   379                  rv = json_parse_const(&uc, ue, "false", sizeof("false"),
   380                      lvl + 1);
   381                  t = JSON_CONSTANT;
   382                  break;
   383          case 'n':
   384                  rv = json_parse_const(&uc, ue, "null", sizeof("null"), lvl + 1);
   385                  t = JSON_CONSTANT;
   386                  break;
   387          default:
   388                  --uc;
   389                  rv = json_parse_number(&uc, ue, lvl + 1);
   390                  t = JSON_NUMBER;
   391                  break;
   392          }
   393          if (rv)
   394                  st[t]++;
   395          uc = json_skip_space(uc, ue);
   396  out:
   397          DPRINTF("End general: ", uc, *ucp);
   398          *ucp = uc;
   399          if (lvl == 0)
   400                  return rv && uc == ue && (st[JSON_ARRAYN] || st[JSON_OBJECT]);
   401          return rv;
   402  }
